 static GameObject Box(string n,Vector3 v,Vector3 s,Material m){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(p,false);g.transform.localPosition=v;g.transform.localScale=s;g.GetComponent<Renderer>().sharedMaterial=m;return g;}
