 static void Print(string name,Vector3 pos,Vector2 size,Material mat,Vector2 bl,Vector2 br,Vector2 tr,Vector2 tl){var mesh=new Mesh();mesh.name=name;mesh.vertices=new[]{new Vector3(-size.x/2,-size.y/2,0),new Vector3(size.x/2,-size.y/2,0),new Vector3(size.x/2,size.y/2,0),new Vector3(-size.x/2,size.y/2,0)};mesh.uv=new[]{bl,br,tr,tl};mesh.triangles=new[]{0,2,1,0,3,2};mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,A+name+".asset");var g=new GameObject(name);g.transform.SetParent(p,false);g.transform.localPosition=pos;g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;}
