 static void Rounded(string name,Vector3 pos,float w,float h,float depth,float radius,Material mat){var verts=new List<Vector3>();var tri=new List<int>();int steps=8;for(int face=0;face<2;face++){float z=face==0?-depth/2:depth/2;verts.Add(new Vector3(0,0,z));for(int c=0;c<4;c++)for(int k=0;k<=steps;k++){float a=(c*90+k*90f/steps)*Mathf.Deg2Rad;float cx=c==0||c==3?w/2-radius:-w/2+radius,cy=c<2?h/2-radius:-h/2+radius;verts.Add(new Vector3(cx+radius*Mathf.Cos(a),cy+radius*Mathf.Sin(a),z));}}int n=4*(steps+1),stride=n+1;for(int i=0;i<n;i++){int a=i+1,b=(i+1)%n+1;tri.AddRange(new[]{0,b,a,stride,stride+a,stride+b,a,b,stride+b,a,stride+b,stride+a});}var mesh=new Mesh();mesh.vertices=verts.ToArray();mesh.triangles=tri.ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,A+name+".asset");var g=new GameObject(name);g.transform.SetParent(p,false);g.transform.localPosition=pos;g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;g.AddComponent<BoxCollider>().size=new Vector3(w,h,depth);}
