 B("ACDB distribution enclosure",1.6f,1.19f,-.14f,.64f,.71f,.23f,grey);B("ACDB door",1.6f,1.19f,-.263f,.59f,.66f,.024f,ivory);B("ACDB meter black bezel",1.64f,1.38f,-.284f,.19f,.18f,.022f,black);B("ACDB meter screen",1.64f,1.4f,-.298f,.145f,.095f,.008f,grey);for(int k=0;k<3;k++)B("Meter digit line",1.64f,1.42f-k*.025f,-.304f,.1f,.009f,.003f,green);B("ACDB red latch",1.89f,1.15f,-.288f,.018f,.06f,.017f,red);Plate("AC COMBINER\nDISTRIBUTION\nBOARD (ACDB)",1.6f,1.83f,.55f);
