 static Vector2 PanelPoint(float x,float y){var src=new[]{new Vector2(145,586),new Vector2(714,558),new Vector2(710,149),new Vector2(142,114)};var dst=new[]{new Vector2(-.47f,-.4f),new Vector2(.47f,-.4f),new Vector2(.47f,.4f),new Vector2(-.47f,.4f)};foreach(var ids in new[]{new[]{0,2,1},new[]{0,3,2}}){var a=src[ids[0]];var b=src[ids[1]];var c=src[ids[2]];float d=(b.y-c.y)*(a.x-c.x)+(c.x-b.x)*(a.y-c.y);float u=((b.y-c.y)*(x-c.x)+(c.x-b.x)*(y-c.y))/d;float v=((c.y-a.y)*(x-c.x)+(a.x-c.x)*(y-c.y))/d;float w=1-u-v;if(u>=-.001f&&v>=-.001f&&w>=-.001f)return dst[ids[0]]*u+dst[ids[1]]*v+dst[ids[2]]*w+new Vector2(0,1.99f);}throw new Exception("Pixel outside fascia");}
 public static string AlignMeters(){
 var parent=GameObject.Find("Blue training panel and motor").transform;
 float[,] meters={{195,179,265,245},{282,181,350,247},{367,187,434,250},{447,190,514,252},{531,196,595,260},{610,202,674,265},{281,318,351,386},{368,322,437,389},{447,328,514,391},{197,442,268,510},{282,444,351,510},{369,443,438,509},{451,444,517,510}};
 for(int i=0;i<13;i++){float x0=meters[i,0],y0=meters[i,1],x1=meters[i,2],y1=meters[i,3];var centre=PanelPoint((x0+x1)/2,(y0+y1)/2);var a=PanelPoint(x0,y0);var b=PanelPoint(x1,y1);float w=Mathf.Abs(b.x-a.x),h=Mathf.Abs(b.y-a.y);var box=parent.Find("Analog meter "+(i+1));var face=parent.Find("Analog meter scale "+(i+1));box.localPosition=new Vector3(centre.x,centre.y,-.16f);box.localScale=new Vector3(w+.005f,h+.005f,.025f);face.localPosition=new Vector3(centre.x,centre.y,-.174f);face.localScale=new Vector3(w/.112f,h/.11f,1);}
 var rings=parent.GetComponentsInChildren<Transform>().Where(t=>t.name=="Dummy load socket ring").ToArray();var centres=parent.GetComponentsInChildren<Transform>().Where(t=>t.name=="Dummy load socket centre").ToArray();for(int i=0;i<4;i++){var q=PanelPoint(i==3?641:603+(i*37),i==3?337:298);rings[i].localPosition=new Vector3(q.x,q.y,-.177f);centres[i].localPosition=new Vector3(q.x,q.y,-.195f);}
 string[] names={"ON red pushbutton","START green pushbutton","Green indicator","STOP yellow switch","Output rocker"};float[,] pixels={{556,455},{585,455},{556,487},{585,487},{646,471}};for(int i=0;i<names.Length;i++){var q=PanelPoint(pixels[i,0],pixels[i,1]);var t=parent.Find(names[i]);t.localPosition=new Vector3(q.x,q.y,t.localPosition.z);}
 // Separate front and side normals to keep the inverter face planar.
 foreach(string name in new[]{"Huawei rounded inverter","Huawei dark badge"}){var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(A+name+".asset");var old=mesh.vertices;var ind=mesh.triangles;var v=new Vector3[ind.Length];var tr=new int[ind.Length];for(int i=0;i<ind.Length;i++){v[i]=old[ind[i]];tr[i]=i;}mesh.Clear();mesh.vertices=v;mesh.triangles=tr;mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);}
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());return "Meters and sockets aligned to photograph";
 }
